// Proportional 1-bit typefaces for the status screen, generated by tools/ttf2c.py from OFL fonts.
#pragma once
#include <stdint.h>

typedef struct {
    uint16_t cp;      // Unicode code point
    uint8_t w, h;     // bitmap size; rows padded to whole bytes, MSB = leftmost pixel
    int16_t x, y;     // bitmap offset from the pen position (x) and from the baseline (y, negative = above)
    uint8_t adv;      // advance width
    uint32_t off;     // offset into GLYPH_BITS
} pglyph_t;

typedef struct {
    uint8_t size, ascent, descent;
    uint8_t count;
    const pglyph_t *glyphs; // sorted by code point
} pfont_t;

#define TYPEFACE_COUNT 7
#define VALUE_SIZES 4 // 46, 36, 28, 22 px
#define SUB_SIZES 3   // 21, 19, 17 px

typedef struct {
    const char *style, *name; // "Clean" / "Inter": the web UI shows the style
    const pfont_t *time_land, *time_port, *ampm, *date_land, *date_port;
    const pfont_t *value[VALUE_SIZES]; // largest first
    const pfont_t *sub[SUB_SIZES];
} typeface_t;

extern const typeface_t TYPEFACES[TYPEFACE_COUNT];
extern const pfont_t *const LABEL_FONT; // small caps labels and tags, the same for every typeface
extern const uint8_t GLYPH_BITS[];
